{
  "iteration": 3,
  "pcvs": [
    {
      "name": "moved_requests",
      "expression": "sum(i < self.num_reqs for i in self.batch_update_builder.removed)",
      "rationale": "Counts complete request-state moves, the dominant repeated work."
    },
    {
      "name": "removed_requests",
      "expression": "len(self.batch_update_builder.removed)",
      "rationale": "Captures removal-dependent scanning and list trimming."
    },
    {
      "name": "nonempty_condensation",
      "expression": "int(bool(self.batch_update_builder.removed) and self.num_reqs > 0)",
      "rationale": "Separates full condensation from early-return paths."
    }
  ],
  "hypothesis": "Movement count, removal count, and the condensation branch explain the structural cost. The fitted generator contribution was negligible, so removing that feature should retain the useful explanatory state without unnecessary fragmentation."
}
